(() => { const pins = [...document.querySelectorAll('.leaflet-marker-icon')].map(m => { const r = m.getBoundingClientRect(), lab = m.querySelector('.og-pin__label'), hood = m.classList.contains('og-hood-marker');
   return { name: lab ? lab.textContent : (m.textContent || '').trim().slice(0, 40), hood, pin: !!m.querySelector('.og-pin'), x: r.x, y: r.y, w: r.width, h: r.height }; });
 const z = (document.body.innerText.match(/Z(\d+)/) || [])[1]; const ll = (document.body.innerText.match(/([\d.]+)°N\s+([\d.]+)°E/) || []);
 let pre = document.getElementById('__dump'); if (!pre) { pre = document.createElement('pre'); pre.id = '__dump'; pre.style.cssText = 'position:fixed;left:0;top:0;width:1px;height:1px;overflow:hidden;opacity:0;white-space:pre;'; document.body.appendChild(pre); }
 pre.textContent = JSON.stringify({ zoom: +z, center: [+ll[1], +ll[2]], viewport: [innerWidth, innerHeight], pins }); })()

